// Fills build-time tokens in edition FAQ answers (unit 2pv). Counts come from
// src/data/reader-languages.json (generated by scripts/gen-sitemap-read.mjs from the community
// registry and lang-audio.json) and are never typed. FAIL CLOSED: a token that is not filled
// (unknown name, or a count missing/zero because the source went stale) throws, so the build
// fails instead of publishing "{{...}}" or a wrong number.
export function faqTokenValues(readerLanguages) {
	const read = readerLanguages?.languages?.length ?? 0;
	const audio = readerLanguages?.audioLanguages?.length ?? 0;
	if (!read) throw new Error('faq-tokens: reader-languages.json has no languages');
	if (!audio) throw new Error('faq-tokens: reader-languages.json has no audioLanguages (regenerate with gen-sitemap-read.mjs)');
	if (audio > read) throw new Error(`faq-tokens: audio ${audio} exceeds read ${read}`);
	return { READ_COUNT: String(read), AUDIO_COUNT: String(audio) };
}

export function fillFaqTokens(text, values, where = 'faq') {
	const out = text.replace(/\{\{([A-Z_]+)\}\}/g, (m, name) => {
		if (!(name in values)) throw new Error(`faq-tokens: unknown token ${m} in ${where}`);
		return values[name];
	});
	if (/\{\{|\}\}/.test(out)) throw new Error(`faq-tokens: unfilled token left in ${where}`);
	return out;
}
